"""Data models for Phase 3: Theming (Discovery, Classification, Ranking)."""

from typing import Annotated

from pydantic import BaseModel, ConfigDict, Field

from pulse.models import Source


class ThemeSpec(BaseModel):
    """Specification of a discovered theme generated by LLM synthesis."""

    model_config = ConfigDict(extra="forbid")

    theme_id: str = Field(description="Unique short theme identifier, e.g. t1, t2, ..., t5")
    name: str = Field(description="Actionable, product-specific theme name")
    definition: str = Field(description="1-2 sentence description defining scope of the theme")
    inclusion_criteria: list[str] = Field(
        default_factory=list,
        description="Key topics, symptoms, or user quotes included in this theme",
    )
    exclusion_criteria: list[str] = Field(
        default_factory=list,
        description="Topics or symptoms excluded and redirected elsewhere or to other",
    )


class DiscoveredThemes(BaseModel):
    """Container for the structured theme discovery response."""

    model_config = ConfigDict(extra="forbid")

    themes: Annotated[
        list[ThemeSpec],
        Field(
            min_length=1, max_length=5, description="List of at most 5 discovered product themes"
        ),
    ]


class ClassificationItem(BaseModel):
    """Classification result for an individual review within a batch."""

    model_config = ConfigDict(extra="forbid")

    rid: str = Field(description="Pseudonymous review ID (e.g. rid_b8c7b88857)")
    theme_id: str = Field(
        description="Assigned theme identifier (e.g. t1..t5) or 'other' if unclassified"
    )
    confidence: float = Field(
        ge=0.0,
        le=1.0,
        description="Model confidence score between 0.0 and 1.0",
    )


class BatchClassificationResult(BaseModel):
    """Structured response for a batch classification request."""

    model_config = ConfigDict(extra="forbid")

    items: list[ClassificationItem] = Field(
        description="Classification results for each review in the batch"
    )


class ReviewAssignment(BaseModel):
    """Persisted record of review-to-theme assignment."""

    model_config = ConfigDict(extra="forbid")

    rid: str = Field(description="Review ID")
    theme_id: str = Field(description="Assigned theme ID (t1..t5 or other)")
    confidence: float = Field(ge=0.0, le=1.0, description="Classification confidence")
    source: Source = Field(description="Store source: play_store or app_store")
    rating: int = Field(ge=1, le=5, description="Review star rating")
    helpful_votes: int = Field(default=0, ge=0, description="Review helpful votes count")
